import { lstatSync, realpathSync } from "node:fs";
import { isAbsolute, relative, resolve, sep } from "node:path";

/**
 * The provenance of a request that may write outside the workspace.
 *
 * `trusted-system` and `direct-operator` are the only sources that authorize
 * an external write.  All other values are deliberately untrusted.
 */
export type WorkspaceExternalWriteSource =
  | "trusted-system"
  | "direct-operator"
  | "external"
  | "derived"
  | "invalid"
  | "missing";

export type WorkspaceExternalWriteProvenance = {
  source?: WorkspaceExternalWriteSource | string | null;
};

export type WorkspaceExternalWriteProvenanceDecision = {
  allowed: boolean;
  source: WorkspaceExternalWriteSource;
  trusted: boolean;
  reason?: "missing-provenance" | "invalid-provenance" | "untrusted-provenance" | "trusted-provenance";
};

export class WorkspaceExternalWriteProvenanceError extends Error {
  readonly code = "WORKSPACE_EXTERNAL_WRITE_PROVENANCE_DENIED";
  readonly source: WorkspaceExternalWriteSource;

  constructor(source: WorkspaceExternalWriteSource, message?: string) {
    super(
      message ??
        `Workspace-external write denied: source ${JSON.stringify(source)} is not trusted-system or direct-operator`,
    );
    this.name = "WorkspaceExternalWriteProvenanceError";
    this.source = source;
  }
}

export type WorkspaceExternalWritePathPolicy = {
  workspaceRoot: string;
  targetPath: string;
};

export type WorkspaceExternalWritePathDecision = {
  outsideWorkspace: boolean;
  pathEscape: boolean;
  reason?:
    | "inside-workspace"
    | "absolute-external-path"
    | "parent-directory-escape"
    | "symlink-or-junction-alias"
    | "hard-link-alias"
    | "unresolvable-path";
};

const TRUSTED_SOURCES = new Set<WorkspaceExternalWriteSource>([
  "trusted-system",
  "direct-operator",
]);

function canonicalSource(value: unknown): WorkspaceExternalWriteSource {
  if (typeof value !== "string") return "invalid";
  const normalized = value.trim().toLowerCase().replace(/[_\s]+/g, "-");
  switch (normalized) {
    case "trusted-system":
    case "trusted":
    case "system":
      return "trusted-system";
    case "direct-operator":
    case "operator":
      return "direct-operator";
    case "external":
      return "external";
    case "derived":
      return "derived";
    case "invalid":
      return "invalid";
    case "missing":
    case "unknown":
      return "missing";
    default:
      return "invalid";
  }
}

export function classifyWorkspaceExternalWriteProvenance(
  provenance: WorkspaceExternalWriteProvenance | WorkspaceExternalWriteSource | string | null | undefined,
): WorkspaceExternalWriteSource {
  if (provenance == null) return "missing";
  if (typeof provenance === "string") return canonicalSource(provenance);
  if (typeof provenance !== "object" || !("source" in provenance)) return "invalid";
  return canonicalSource(provenance.source);
}

export function isTrustedWorkspaceExternalWriteSource(
  provenance: WorkspaceExternalWriteProvenance | WorkspaceExternalWriteSource | string | null | undefined,
): boolean {
  return TRUSTED_SOURCES.has(classifyWorkspaceExternalWriteProvenance(provenance));
}

export function evaluateWorkspaceExternalWriteProvenance(
  provenance: WorkspaceExternalWriteProvenance | WorkspaceExternalWriteSource | string | null | undefined,
): WorkspaceExternalWriteProvenanceDecision {
  const source = classifyWorkspaceExternalWriteProvenance(provenance);
  const trusted = TRUSTED_SOURCES.has(source);
  let reason: WorkspaceExternalWriteProvenanceDecision["reason"];
  if (source === "missing") reason = "missing-provenance";
  else if (source === "invalid") reason = "invalid-provenance";
  else if (!trusted) reason = "untrusted-provenance";
  else reason = "trusted-provenance";
  return { allowed: trusted, source, trusted, reason };
}

export function assertTrustedWorkspaceExternalWriteProvenance(
  provenance: WorkspaceExternalWriteProvenance | WorkspaceExternalWriteSource | string | null | undefined,
): WorkspaceExternalWriteSource {
  const source = classifyWorkspaceExternalWriteProvenance(provenance);
  if (!TRUSTED_SOURCES.has(source)) {
    throw new WorkspaceExternalWriteProvenanceError(source);
  }
  return source;
}

function existingAncestor(path: string): string | undefined {
  let candidate = resolve(path);
  while (true) {
    try {
      lstatSync(candidate);
      return candidate;
    } catch {
      const parent = resolve(candidate, "..");
      if (parent === candidate) return undefined;
      candidate = parent;
    }
  }
}

function inodeKey(path: string): string | undefined {
  try {
    const stat = lstatSync(path);
    if (!stat.isFile()) return undefined;
    return `${stat.dev}:${stat.ino}`;
  } catch {
    return undefined;
  }
}

/**
 * Classifies the target using the workspace boundary.  This helper performs no
 * writes.  It is intentionally used only for external targets; in-workspace
 * writes retain their existing behavior.
 */
export function evaluateWorkspaceExternalWritePath(
  policy: WorkspaceExternalWritePathPolicy,
): WorkspaceExternalWritePathDecision {
  const workspaceRoot = resolve(policy.workspaceRoot);
  const targetPath = resolve(policy.targetPath);
  const rel = relative(workspaceRoot, targetPath);
  const insideWorkspace = rel === "" || (!rel.startsWith(`..${sep}`) && rel !== ".." && !isAbsolute(rel));
  if (insideWorkspace) return { outsideWorkspace: false, pathEscape: false, reason: "inside-workspace" };

  if (isAbsolute(policy.targetPath)) {
    return { outsideWorkspace: true, pathEscape: true, reason: "absolute-external-path" };
  }

  const ancestor = existingAncestor(targetPath);
  if (!ancestor) {
    return { outsideWorkspace: true, pathEscape: true, reason: "unresolvable-path" };
  }

  try {
    const realWorkspace = realpathSync.native(workspaceRoot);
    const realTarget = realpathSync.native(ancestor);
    const realRel = relative(realWorkspace, realTarget);
    if (
      realRel === ".." ||
      realRel.startsWith(`..${sep}`) ||
      isAbsolute(realRel)
    ) {
      return { outsideWorkspace: true, pathEscape: true, reason: "symlink-or-junction-alias" };
    }
  } catch {
    return { outsideWorkspace: true, pathEscape: true, reason: "unresolvable-path" };
  }

  const targetInode = inodeKey(targetPath);
  if (targetInode) {
    const workspaceInode = inodeKey(workspaceRoot);
    if (workspaceInode && workspaceInode === targetInode) {
      return { outsideWorkspace: true, pathEscape: true, reason: "hard-link-alias" };
    }
  }

  return {
    outsideWorkspace: true,
    pathEscape: true,
    reason: targetPath.split(/[\\/]/).includes("..")
      ? "parent-directory-escape"
      : "absolute-external-path",
  };
}

/**
 * Central guard for workspace-external writes.  The caller must invoke this
 * before any filesystem mutation.  Provenance is checked first so an
 * untrusted request is rejected without even touching the target.
 */
export function assertWorkspaceExternalWriteAllowed(
  provenance: WorkspaceExternalWriteProvenance | WorkspaceExternalWriteSource | string | null | undefined,
  policy?: WorkspaceExternalWritePathPolicy,
): WorkspaceExternalWriteSource {
  const source = assertTrustedWorkspaceExternalWriteProvenance(provenance);
  if (policy) evaluateWorkspaceExternalWritePath(policy);
  return source;
}

export const workspaceExternalWriteProvenancePolicy = {
  classify: classifyWorkspaceExternalWriteProvenance,
  evaluate: evaluateWorkspaceExternalWriteProvenance,
  isTrusted: isTrustedWorkspaceExternalWriteSource,
  assertTrusted: assertTrustedWorkspaceExternalWriteProvenance,
  evaluatePath: evaluateWorkspaceExternalWritePath,
  assertAllowed: assertWorkspaceExternalWriteAllowed,
} as const;

export default workspaceExternalWriteProvenancePolicy;

